import pandas as pd
import re

file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)
df = df[df['Record ID'].astype(str).str.startswith('MU-')].copy()

def parse_amount(val):
    if pd.isna(val):
        return 0
    s = str(val).strip()
    if s.lower() in ['', '-', 'na', 'nan', 'none']:
        return 0
    # Remove currency symbols and commas
    s_clean = s.replace('₹', '').replace(',', '').strip()
    # Some values may have spaces
    # Try regex for number + unit
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s_clean)
    if m:
        num = float(m.group(1))
        unit = m.group(2)
        if not unit:
            # maybe plain number
            return int(num)
        unit_lower = unit.lower()
        if unit_lower.startswith('l'):  # lakh
            return int(num * 100000)
        if unit_lower.startswith('cr'):
            return int(num * 10000000)
        if unit_lower.startswith('k'):
            return int(num * 1000)
        # unknown
        return int(num)
    # fallback try numeric
    try:
        return int(float(s_clean))
    except:
        return 0

df['Amount INR'] = df['Amount'].apply(parse_amount)

# Summary counts
print(df['Amount'].value_counts(dropna=False))
print('Rows:', len(df))
print('Total INR:', df['Amount INR'].sum())
# Check for any unparsed non-zero strings
unparsed = df[~df['Amount'].astype(str).str.match(r'^[0-9₹,\.\s]*[a-zA-Z]*$')]
print('Potential unparsed rows:', len(unparsed))
print(unparsed[['Record ID','Amount']].head())
